1	package org.springframework.samples.petclinic.rest.function.common;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
5	
6	/**
7	 * Derives an owner's {@link OwnerDto.OwnerSegmentEnum segment}, formatted {@code "<TIER>_<AREA>"}.
8	 *
9	 * <p>TIER is {@code PREMIUM} when the owner's {@link MembershipLevels#of(Owner) membership level} is
10	 * 3 or more, otherwise {@code STANDARD}. AREA is {@code METRO} when the owner's
11	 * {@link Localities#region(String, String) locality} is a known region (NSW, VIC or QLD), otherwise
12	 * {@code REGIONAL}. The possible values are {@code PREMIUM_METRO}, {@code PREMIUM_REGIONAL},
13	 * {@code STANDARD_METRO} and {@code STANDARD_REGIONAL}.
14	 */
15	public final class OwnerSegments {
16	
17	    /** Membership level at or above which the owner is in the PREMIUM tier. */
18	    private static final int PREMIUM_LEVEL = 3;
19	
20	    private OwnerSegments() {
21	    }
22	
23	    /** Computes the owner's segment. */
24	    public static OwnerDto.OwnerSegmentEnum of(Owner owner) {
25	        String tier = MembershipLevels.of(owner) >= PREMIUM_LEVEL ? "PREMIUM" : "STANDARD";
26	        String region = Localities.region(owner.getPostcode(), owner.getCity());
27	        String area = Localities.UNKNOWN.equals(region) ? "REGIONAL" : "METRO";
28	        return OwnerDto.OwnerSegmentEnum.valueOf(tier + "_" + area);
29	    }
30	}
